import React, { useState, useEffect } from 'react';
import { ref, onValue, push, update, set } from 'firebase/database';
import { database } from '../Firebase';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Modal, Button, Form, Row, Col } from 'react-bootstrap';

const AddStock = () => {
  const [fields, setFields] = useState([]);
  const [stockList, setStockList] = useState([]);
  const [formData, setFormData] = useState({});
  const [editingId, setEditingId] = useState(null);
  const [showFieldModal, setShowFieldModal] = useState(false);
  const [newField, setNewField] = useState({
    label: '',
    name: '',
    type: 'text',
    required: false,
  });

  const today = new Date().toLocaleDateString('en-GB').replace(/\//g, '-');

  // Fetch field template and today's stock entries
  useEffect(() => {
    const fRef = ref(database, 'fieldTemplates/stock');
    onValue(fRef, (snap) => {
      if (snap.val()) setFields(snap.val());
    });
    const sRef = ref(database, `stock/${today}`);
    onValue(sRef, (snap) => {
      const val = snap.val();
      setStockList(
        val ? Object.entries(val).map(([id, data]) => ({ id, ...data })) : []
      );
    });
  }, [today]);

  const handleFormChange = (e) =>
    setFormData((prev) => ({ ...prev, [e.target.name]: e.target.value }));

  const startEdit = (item) => {
    const copy = {};
    fields.forEach((f) => (copy[f.name] = item[f.name] || ''));
    setFormData(copy);
    setEditingId(item.id);
  };

  const cancelEdit = () => {
    setFormData({});
    setEditingId(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const timestamp = new Date()
      .toLocaleString('en-GB', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hour12: true,
      })
      .replace(',', '');
    const payload = { ...formData, datewithtime: timestamp };

    const base = ref(database, `stock/${today}`);
    if (editingId) {
      await update(ref(database, `stock/${today}/${editingId}`), payload);
      alert('✔️ Stock updated');
    } else {
      await push(base, payload);
      alert('✔️ Stock added');
    }
    cancelEdit();
  };

  const openFieldsModal = () => setShowFieldModal(true);
  const closeFieldsModal = () => setShowFieldModal(false);

  const handleNewFieldChange = (e) => {
    const { name, value, type, checked } = e.target;
    setNewField((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const addFieldDef = () => {
    if (!newField.label || !newField.name)
      return alert('Label and name required');
    const updated = [...fields, newField];
    setFields(updated);
    set(ref(database, 'fieldTemplates/stock'), updated);
    setNewField({ label: '', name: '', type: 'text', required: false });
  };

  const deleteFieldDef = (idx) => {
    const updated = [...fields];
    updated.splice(idx, 1);
    setFields(updated);
    set(ref(database, 'fieldTemplates/stock'), updated);
  };

  return (
    <div className='container shadow-lg p-4 my-4 bg-white rounded'>
      <h4 className='text-center mb-3'>Add / Edit Stock</h4>
      <div className='text-end mb-2'>
        <Button variant='secondary' onClick={openFieldsModal}>
          ⚙️ Modify Stock Fields
        </Button>
      </div>

      {/* Stock entry form */}
      <form onSubmit={handleSubmit}>
        <div className='row mb-3'>
          {fields.map((f, idx) => (
            <div className='col-md-6 pt-3' key={idx}>
              <label className='form-label'>{f.label}</label>
              <input
                type={f.type}
                name={f.name}
                className='form-control'
                value={formData[f.name] || ''}
                onChange={handleFormChange}
                required={f.required}
                placeholder={`Enter ${f.label}`}
              />
            </div>
          ))}
        </div>
        <div className='text-center mt-3'>
          <button type='submit' className='btn btn-primary px-4'>
            {editingId ? 'Update' : 'Submit'}
          </button>
          {editingId && (
            <Button variant='secondary' className='ms-2' onClick={cancelEdit}>
              Cancel
            </Button>
          )}
        </div>
      </form>
    </div>
  );
};

export default AddStock;
