import React, { useEffect, useState } from 'react';
import { ref, onValue } from 'firebase/database';
import { database } from '../Firebase';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';
import 'bootstrap/dist/css/bootstrap.min.css';

const StockDashboard = () => {
  const [stockData, setStockData] = useState({});
  const [filteredData, setFilteredData] = useState({});
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [itemFilter, setItemFilter] = useState('');
  const [stockFields, setStockFields] = useState([]);
  const [stockHistory, setStockHistory] = useState([]); // array version
  const [viewMode, setViewMode] = useState('stock');
  const [tableHeaders, setTableHeaders] = useState([]);

  useEffect(() => {
    const stockHistoryRef = ref(database, 'stockhistory');
    onValue(stockHistoryRef, (snapshot) => {
      const data = snapshot.val();
      const allLogs = [];
      const dynamicKeys = new Set();

      if (data) {
        Object.entries(data).forEach(([dateKey, empEntries]) => {
          Object.entries(empEntries).forEach(([empId, logs]) => {
            Object.entries(logs).forEach(([logId, logData]) => {
              const fullLog = {
                date: dateKey,
                employeeId: empId,
                ...logData,
              };
              Object.keys(fullLog).forEach((key) => dynamicKeys.add(key));
              allLogs.push(fullLog);
            });
          });
        });
      }

      setStockHistory(allLogs);
      setTableHeaders(Array.from(dynamicKeys));
    });
  }, []);

  useEffect(() => {
    const fieldRef = ref(database, 'fieldTemplates/stock');
    onValue(fieldRef, (snapshot) => {
      const fields = snapshot.val();
      if (fields) setStockFields(fields);
    });

    const stockRef = ref(database, 'stock');
    onValue(stockRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setStockData(data);
        const today = new Date();
        const formatted = formatDate(today);
        const todayData = { [formatted]: data[formatted] || {} };
        setStartDate(today);
        setEndDate(today);
        setItemFilter('');
        setFilteredData(todayData);
      }
    });
  }, []);

  const formatDate = (date) =>
    date
      .toLocaleDateString('en-GB')
      .split('/')
      .map((x) => x.padStart(2, '0'))
      .join('-');

  const filterData = () => {
    if (viewMode === 'stock') {
      const filtered = {};
      Object.entries(stockData).forEach(([dateKey, entries]) => {
        const [day, month, year] = dateKey.split('-');
        const dateObj = new Date(`${year}-${month}-${day}`);
        const isInRange =
          (!startDate || dateObj >= new Date(startDate.setHours(0, 0, 0, 0))) &&
          (!endDate || dateObj <= new Date(endDate.setHours(23, 59, 59, 999)));

        Object.entries(entries).forEach(([id, record]) => {
          const filterField = stockFields[0]?.name || 'name';
          const matchesItem = itemFilter
            ? record?.[filterField]
                ?.toLowerCase()
                .includes(itemFilter.toLowerCase())
            : true;
          if (matchesItem && isInRange) {
            if (!filtered[dateKey]) filtered[dateKey] = {};
            filtered[dateKey][id] = record;
          }
        });
      });
      setFilteredData(filtered);
    }
  };

  const filterToday = () => {
    const today = new Date();
    const formatted = formatDate(today);
    const todayData = { [formatted]: stockData[formatted] || {} };
    setStartDate(today);
    setEndDate(today);
    setItemFilter('');
    setFilteredData(todayData);
  };

  const exportExcel = async () => {
    const borderStyle = {
      top: { style: 'thin' },
      left: { style: 'thin' },
      bottom: { style: 'thin' },
      right: { style: 'thin' },
    };

    // Helper function inside exportExcel to convert column number to letter
    function getExcelColumnLetter(colIndex) {
      let dividend = colIndex;
      let columnName = '';
      let modulo;

      while (dividend > 0) {
        modulo = (dividend - 1) % 26;
        columnName = String.fromCharCode(65 + modulo) + columnName;
        dividend = Math.floor((dividend - modulo) / 26);
      }

      return columnName;
    }

    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet(
      viewMode === 'stock' ? 'Stock Report' : 'Stock History'
    );

    // Calculate number of columns dynamically based on viewMode
    const numColumns =
      viewMode === 'stock' ? 1 + stockFields.length : tableHeaders.length;

    // Get the last column letter for merging title cells
    const lastColLetter = getExcelColumnLetter(numColumns);

    // Merge title cells dynamically
    worksheet.mergeCells(`A1:${lastColLetter}1`);

    const reportTitle =
      viewMode === 'stock' ? 'Stock Report' : 'Stock History Report';
    const titleCell = worksheet.getCell('A1');
    titleCell.value = reportTitle;
    titleCell.font = { size: 16, bold: true };
    titleCell.alignment = { vertical: 'middle', horizontal: 'center' };
    titleCell.border = borderStyle;

    // Date Range Row (with blank row before and after)
    worksheet.addRow([]);
    const dateRangeRow = worksheet.addRow([
      'From:',
      startDate ? startDate.toLocaleDateString('en-GB') : 'N/A',
      'To:',
      endDate ? endDate.toLocaleDateString('en-GB') : 'N/A',
    ]);
    worksheet.addRow([]);

    // Add borders and alignment to the date range row cells
    dateRangeRow.eachCell((cell) => {
      cell.border = borderStyle;
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
      cell.font = { bold: true };
    });

    let headerRow;
    if (viewMode === 'stock') {
      const headers = ['Date', ...stockFields.map((field) => field.label)];
      headerRow = worksheet.addRow(headers);

      // Style header row
      headerRow.eachCell((cell) => {
        cell.font = { bold: true };
        cell.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FFCCE5FF' },
        };
        cell.border = borderStyle;
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
      });

      // Add data rows with styling
      Object.entries(filteredData).forEach(([date, records]) => {
        Object.values(records).forEach((record) => {
          const rowValues = [date];
          stockFields.forEach((field) => {
            rowValues.push(record[field.name] || '');
          });
          const row = worksheet.addRow(rowValues);

          row.eachCell((cell) => {
            cell.alignment = { vertical: 'middle', horizontal: 'center' };
            cell.border = borderStyle;
          });
        });
      });
    } else {
      headerRow = worksheet.addRow(tableHeaders);

      // Style header row
      headerRow.eachCell((cell) => {
        cell.font = { bold: true };
        cell.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FFCCE5FF' },
        };
        cell.border = borderStyle;
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
      });

      // Add data rows with styling
      stockHistory
        .filter((entry) => {
          const [d, m, y] = entry.date.split('-');
          const dateObj = new Date(`${y}-${m}-${d}`);
          return (
            (!startDate ||
              dateObj >= new Date(startDate.setHours(0, 0, 0, 0))) &&
            (!endDate || dateObj <= new Date(endDate.setHours(23, 59, 59, 999)))
          );
        })
        .filter((entry) =>
          itemFilter
            ? entry.name?.toLowerCase().includes(itemFilter.toLowerCase())
            : true
        )
        .forEach((entry) => {
          const rowValues = tableHeaders.map((key) => entry[key] || '');
          const row = worksheet.addRow(rowValues);

          row.eachCell((cell) => {
            cell.alignment = { vertical: 'middle', horizontal: 'center' };
            cell.border = borderStyle;
          });
        });
    }

    // Freeze header row
    worksheet.views = [
      {
        state: 'frozen',
        ySplit: headerRow.number,
      },
    ];

    // Auto-width columns
    worksheet.columns.forEach((col) => {
      let maxLength = 10;
      col.eachCell?.((cell) => {
        const val = cell.value ? cell.value.toString() : '';
        maxLength = Math.max(maxLength, val.length + 2);
      });
      col.width = maxLength;
    });

    // Export file
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });
    saveAs(blob, `${reportTitle.replace(/\s+/g, '')}.xlsx`);
  };

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.text(
      viewMode === 'stock' ? 'Stock Report' : 'Stock History Report',
      14,
      10
    );

    if (viewMode === 'stock') {
      const head = [['Date', ...stockFields.map((field) => field.label)]];
      const rows = [];
      Object.entries(filteredData).forEach(([date, records]) => {
        Object.values(records).forEach((record) => {
          const row = [date];
          stockFields.forEach((field) => row.push(record[field.name] || ''));
          rows.push(row);
        });
      });
      autoTable(doc, { head, body: rows, startY: 20 });
    } else {
      const head = [tableHeaders];
      const rows = stockHistory
        .filter((entry) => {
          const [d, m, y] = entry.date.split('-');
          const dateObj = new Date(`${y}-${m}-${d}`);
          return (
            (!startDate ||
              dateObj >= new Date(startDate.setHours(0, 0, 0, 0))) &&
            (!endDate || dateObj <= new Date(endDate.setHours(23, 59, 59, 999)))
          );
        })
        .filter((entry) =>
          itemFilter
            ? entry.name?.toLowerCase().includes(itemFilter.toLowerCase())
            : true
        )
        .map((row) => tableHeaders.map((h) => row[h] || ''));
      autoTable(doc, { head, body: rows, startY: 20 });
    }

    doc.save(`${viewMode === 'stock' ? 'Stock' : 'StockHistory'}Report.pdf`);
  };

  return (
    <div className='container mt-5 shadow p-4 bg-white rounded border'>
      <h4 className='text-center mb-4 fw-bold text-primary'>Stock Dashboard</h4>

      <div className='row mb-3'>
        <div className='col-md-4'>
          <label>View Mode</label>
          <select
            className='form-select'
            value={viewMode}
            onChange={(e) => setViewMode(e.target.value)}
          >
            <option value='stock'>Stock View</option>
            <option value='history'>Stock History</option>
          </select>
        </div>
      </div>

      <div className='row g-3 mb-3'>
        <div className='col-md-4'>
          <label>Start Date</label>
          <DatePicker
            className='form-control'
            selected={startDate}
            onChange={(date) => setStartDate(date)}
            dateFormat='dd-MMM-yyyy'
            placeholderText='Select start date'
          />
        </div>
        <div className='col-md-4'>
          <label>End Date</label>
          <DatePicker
            className='form-control'
            selected={endDate}
            onChange={(date) => setEndDate(date)}
            dateFormat='dd-MMM-yyyy'
            placeholderText='Select end date'
          />
        </div>
        <div className='col-md-4'>
          <label>Item Filter</label>
          <input
            type='text'
            className='form-control'
            placeholder='Enter item name'
            value={itemFilter}
            onChange={(e) => setItemFilter(e.target.value)}
          />
        </div>
      </div>

      <div className='row g-3 mb-4'>
        <div className='col-md-4 d-grid'>
          <button className='btn btn-info' onClick={filterData}>
            Filter
          </button>
        </div>
        <div className='col-md-3 d-grid'>
          <button className='btn btn-outline-secondary' onClick={filterToday}>
            Today
          </button>
        </div>
        <div className='col-md-5 d-flex justify-content-end gap-2'>
          <button className='btn btn-success' onClick={exportExcel}>
            Export Excel
          </button>
          <button className='btn btn-danger' onClick={exportPDF}>
            Export PDF
          </button>
        </div>
      </div>

      <div className='mt-3'>
        {viewMode === 'stock' ? (
          Object.keys(filteredData).length === 0 ? (
            <p className='text-center text-muted'>No stock records found.</p>
          ) : (
            Object.entries(filteredData).map(([date, records], index) => (
              <div className='card mb-4 shadow-sm border' key={index}>
                <div className='card-header fw-bold bg-light'>Date: {date}</div>
                <div className='card-body table-responsive'>
                  <table className='table table-bordered table-striped mb-0'>
                    <thead className='table-dark'>
                      <tr>
                        <th>#</th>
                        {stockFields.map((field, i) => (
                          <th key={i}>{field.label}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {Object.values(records).map((entry, idx) => (
                        <tr key={idx}>
                          <td>{idx + 1}</td>
                          {stockFields.map((field, i) => (
                            <td key={i}>{entry[field.name] || ''}</td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))
          )
        ) : (
          <div className='card mb-4 shadow-sm border'>
            <div className='card-header fw-bold bg-light'>
              Stock History Logs
            </div>
            <div className='card-body table-responsive'>
              <table className='table table-bordered table-striped mb-0'>
                <thead className='table-secondary'>
                  <tr>
                    {tableHeaders.map((header, idx) => (
                      <th key={idx}>{header}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {stockHistory.length === 0 ? (
                    <tr>
                      <td colSpan={tableHeaders.length} className='text-center'>
                        No history found
                      </td>
                    </tr>
                  ) : (
                    stockHistory
                      .filter((entry) => {
                        const [d, m, y] = entry.date.split('-');
                        const dateObj = new Date(`${y}-${m}-${d}`);
                        return (
                          (!startDate ||
                            dateObj >=
                              new Date(startDate.setHours(0, 0, 0, 0))) &&
                          (!endDate ||
                            dateObj <=
                              new Date(endDate.setHours(23, 59, 59, 999)))
                        );
                      })
                      .filter((entry) =>
                        itemFilter
                          ? entry.name
                              ?.toLowerCase()
                              .includes(itemFilter.toLowerCase())
                          : true
                      )
                      .map((row, idx) => (
                        <tr key={idx}>
                          {tableHeaders.map((header) => (
                            <td key={header}>{row[header] ?? ''}</td>
                          ))}
                        </tr>
                      ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default StockDashboard;
