import React, { useEffect, useState } from 'react';
import { database } from '../Firebase';
import { ref, get, remove } from 'firebase/database';
import { saveAs } from 'file-saver';
import ExcelJS from 'exceljs';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import 'bootstrap/dist/css/bootstrap.min.css';

const EmployeeDashboard = () => {
  const [employeeData, setEmployeeData] = useState({});
  const [filteredData, setFilteredData] = useState({});
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [employeeIdFilter, setEmployeeIdFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('All'); // All, Given, Return
  const [returnData, setReturnData] = useState({});

  const [allKeys, setAllKeys] = useState([]);
  const [fields, setFields] = useState([]);

  useEffect(() => {
    fetchData().then(() => {
      const today = new Date().toISOString().split('T')[0];
      setStartDate(today);
      setEndDate(today);
      setTypeFilter('Given');
      setTimeout(() => handleFilter(), 100); // allow state to settle before filtering
    });
  }, []);
  useEffect(() => {
    if (startDate && endDate && typeFilter) {
      handleFilter();
    }
  }, [startDate, endDate, typeFilter]);

  const fetchData = async () => {
    const empRef = ref(database, 'employee');
    const returnRef = ref(database, 'employeeReturns');
    const fieldRef = ref(database, 'fieldTemplates/employee');

    const [empSnap, returnSnap, fieldSnap] = await Promise.all([
      get(empRef),
      get(returnRef),
      get(fieldRef),
    ]);

    if (empSnap.exists()) {
      setEmployeeData(empSnap.val());
    }

    if (returnSnap.exists()) {
      setReturnData(returnSnap.val());
    }

    if (fieldSnap.exists()) {
      const fieldsArr = fieldSnap.val();
      setFields(fieldsArr);
      setAllKeys(fieldsArr.map((f) => f.name));
    }
  };

  const computeAllKeys = (data) => {
    const keySet = new Set();
    Object.values(data).forEach((dateGroup) => {
      Object.values(dateGroup).forEach((record) => {
        Object.keys(record).forEach((key) => keySet.add(key));
      });
    });
    // Ensure static keys like name, employeeId, datewithtime appear first
    const ordered = [
      'name',
      'employeeId',
      'stock1',
      'quantity1',
      'stock2',
      'quantity2',
      'datewithtime',
    ];
    const extras = Array.from(keySet).filter((k) => !ordered.includes(k));
    const combined = [...ordered.filter((k) => keySet.has(k)), ...extras];
    setAllKeys(combined);
  };

  const handleFilter = () => {
    if (!startDate || !endDate) return;

    const result = {};

    const processData = (data, type) => {
      Object.entries(data).forEach(([date, entries]) => {
        const [dd, mm, yyyy] = date.split('-');
        const keyDate = new Date(`${yyyy}-${mm}-${dd}`);
        if (new Date(startDate) <= keyDate && keyDate <= new Date(endDate)) {
          Object.entries(entries).forEach(([id, rec]) => {
            if (!employeeIdFilter || rec.employeeId === employeeIdFilter) {
              if (!result[date]) result[date] = {};
              result[date][`${type}-${id}`] = { ...rec, __type: type };
            }
          });
        }
      });
    };

    if (typeFilter === 'All' || typeFilter === 'Given') {
      processData(employeeData, 'Given');
    }

    if (typeFilter === 'All' || typeFilter === 'Return') {
      processData(returnData, 'Return');
    }

    setFilteredData(result);
  };

  const handleTodaySelect = () => {
    const today = new Date().toISOString().split('T')[0];
    setStartDate(today);
    setEndDate(today);
  };

  const handleExcelExport = () => {
    const wb = new ExcelJS.Workbook();
    const ws = wb.addWorksheet('Employee Stock Use Report');

    const reportTitle = 'Employee Stock Use Report';

    // Dynamically determine total number of columns
    const totalColumns = allKeys.length + 2; // 1 for serial, 1 for date

    // Merge top heading across all columns
    ws.mergeCells(1, 1, 1, totalColumns);
    const titleCell = ws.getCell(1, 1);
    titleCell.value = reportTitle;
    titleCell.font = { size: 16, bold: true };
    titleCell.alignment = { horizontal: 'center' };

    // Add table header row: Serial No + Date + Dynamic Keys
    const headers = ['#', 'Date', ...allKeys];
    ws.addRow(headers);

    // Fill data rows
    let serial = 1;
    Object.entries(filteredData).forEach(([date, recs]) => {
      Object.values(recs).forEach((rec) => {
        const rowData = [serial++, date, ...allKeys.map((k) => rec[k] || '')];
        ws.addRow(rowData);
      });
    });

    // Style header row (row 2)
    ws.getRow(2).eachCell((cell) => {
      cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
      cell.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: '4F81BD' },
      };
      cell.alignment = { horizontal: 'center' };
    });

    // Auto column width for all columns
    ws.columns.forEach((col) => {
      let max = 10;
      col.eachCell({ includeEmpty: true }, (c) => {
        const len = c.value ? c.value.toString().length : 0;
        if (len > max) max = len;
      });
      col.width = max + 2;
    });

    // Apply border to all cells (basic grid-like table)
    ws.eachRow((row) => {
      row.eachCell((cell) => {
        cell.border = {
          top: { style: 'thin' },
          left: { style: 'thin' },
          bottom: { style: 'thin' },
          right: { style: 'thin' },
        };
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
      });
    });

    // Export as Excel file
    wb.xlsx.writeBuffer().then((buf) => {
      saveAs(
        new Blob([buf], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        }),
        'Employee_Report.xlsx'
      );
    });
  };

  const handlePDFExport = () => {
    const doc = new jsPDF();
    doc.text('Employee Usage Report', 14, 14);
    const body = [];
    Object.entries(filteredData).forEach(([_, recs]) => {
      Object.values(recs).forEach((rec) => {
        body.push([...allKeys.map((k) => rec[k] || '')]);
      });
    });
    autoTable(doc, { head: [allKeys], body, startY: 20 });
    doc.save('employee_report.pdf');
  };

  const handleDelete = async (date, id) => {
    if (!window.confirm('Delete this entry?')) return;
    try {
      await remove(ref(database, `employee/${date}/${id}`));
      alert('✅ Deleted');
      fetchData();
    } catch (err) {
      alert('❌ Failed: ' + err.message);
    }
  };

  return (
    <div className='container mt-5'>
      <div className='shadow p-4 bg-white rounded border'>
        <h4 className='text-center mb-4 fw-bold text-primary'>
          Employee Dashboard
        </h4>

        {/* Filter Section in 2 Rows */}
        <div className='row g-3'>
          {/* Row 1: Start Date, End Date */}
          <div className='col-md-6 col-lg-3'>
            <label htmlFor='startDate' className='form-label'>
              Start Date
            </label>
            <input
              id='startDate'
              type='date'
              className='form-control'
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
            />
          </div>

          <div className='col-md-6 col-lg-3'>
            <label htmlFor='endDate' className='form-label'>
              End Date
            </label>
            <input
              id='endDate'
              type='date'
              className='form-control'
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
            />
          </div>

          <div className='col-md-6 col-lg-3'>
            <label htmlFor='employeeId' className='form-label'>
              Employee ID
            </label>
            <input
              id='employeeId'
              type='text'
              className='form-control'
              placeholder='All'
              value={employeeIdFilter}
              onChange={(e) => setEmployeeIdFilter(e.target.value)}
            />
          </div>

          <div className='col-md-6 col-lg-3'>
            <label htmlFor='typeFilter' className='form-label'>
              Type
            </label>
            <select
              id='typeFilter'
              className='form-select'
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
            >
              <option value='All'>All</option>
              <option value='Given'>Given</option>
              <option value='Return'>Return</option>
            </select>
          </div>

          {/* Row 2: Filter Button and Today Button */}
          <div className='col-md-6 col-lg-3'>
            <button className='btn btn-info w-100 mb-2' onClick={handleFilter}>
              Filter
            </button>
          </div>

          <div className='col-md-6 col-lg-3'>
            <button
              className='btn btn-outline-secondary w-100 mb-2'
              onClick={handleTodaySelect}
            >
              Today
            </button>
          </div>
          <div className='col-md-6 col-lg-2'>
            <button
              className='btn btn-success mr-5'
              onClick={handleExcelExport}
            >
              Export to Excel
            </button>
          </div>
          <div className='col-md-6 col-lg-2'>
            <button className='btn btn-danger' onClick={handlePDFExport}>
              Export to PDF
            </button>
          </div>
        </div>

        {/* Table section remains unchanged */}
        {Object.keys(filteredData).length === 0 ? (
          <p className='text-center text-muted mt-4'>No records to show.</p>
        ) : (
          Object.entries(filteredData).map(([date, records]) => (
            <div className='card mb-4 shadow-sm border' key={date}>
              <div className='card-header fw-bold bg-light'>Date: {date}</div>
              <div className='card-body table-responsive'>
                <table className='table table-bordered table-striped'>
                  <thead className='table-dark'>
                    <tr>
                      <th>#</th>
                      {fields.map((field) => (
                        <th key={field.name}>{field.label}</th>
                      ))}
                      <th>Type</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {Object.entries(records).map(([id, rec], idx) => (
                      <tr key={id}>
                        <td>{idx + 1}</td>
                        {fields.map((field) => (
                          <td key={field.name}>{rec[field.name] || ''}</td>
                        ))}
                        <td>{rec.__type || 'Given'}</td>
                        <td>
                          <button
                            className='btn btn-sm btn-outline-danger'
                            onClick={() =>
                              handleDelete(date, id.replace(/^Given-/, ''))
                            }
                            disabled={!id.startsWith('Given')}
                          >
                            Delete
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default EmployeeDashboard;
