import React, { useState } from 'react';

const TimeAdder = () => {
  const [timeInput, setTimeInput] = useState('');
  const [history, setHistory] = useState([]);
  const [totalHours, setTotalHours] = useState(0);
  const [totalMinutes, setTotalMinutes] = useState(0);
  const [error, setError] = useState('');

  const parseTime = (input) => {
    const [h, m] = input.split('.').map(Number);
    return { hours: h || 0, minutes: m || 0 };
  };

  const formatTime = (hours, minutes) => {
    if (minutes >= 60) {
      hours += Math.floor(minutes / 60);
      minutes = minutes % 60;
    }
    return `${hours}.${minutes.toString().padStart(2, '0')}`;
  };

  const isValidTime = (input) => {
    if (!/^\d+(\.\d{1,2})?$/.test(input)) return false;
    const [h, m] = input.split('.').map(Number);
    return m === undefined || (m >= 0 && m < 60);
  };

  const handleInputChange = (e) => {
    const val = e.target.value;
    setTimeInput(val);
    if (!isValidTime(val)) {
      setError('Invalid time. Minutes must be 0–59 only.');
    } else {
      setError('');
    }
  };

  const handleOperation = (isAdd) => {
    if (!isValidTime(timeInput)) {
      setError('Please enter valid time (e.g. 2.45, 10.30)');
      return;
    }

    const { hours, minutes } = parseTime(timeInput);
    let newHours = totalHours;
    let newMinutes = totalMinutes;

    if (isAdd) {
      newHours += hours;
      newMinutes += minutes;
      setHistory([...history, `+ ${timeInput}`]);
    } else {
      newHours -= hours;
      newMinutes -= minutes;
      setHistory([...history, `– ${timeInput}`]);
    }

    // Normalize
    if (newMinutes < 0) {
      newHours -= Math.ceil(Math.abs(newMinutes) / 60);
      newMinutes = ((newMinutes % 60) + 60) % 60;
    }

    const normalizedTime = formatTime(newHours, newMinutes);
    setTotalHours(parseInt(normalizedTime.split('.')[0]));
    setTotalMinutes(parseInt(normalizedTime.split('.')[1]));
    setTimeInput('');
  };

  return (
    <div className='container mt-5 d-flex'>
      {/* Left side: Total, input, buttons */}

      {/* Right side: History */}
      <div className='w-50 p-3 border-start'>
        <h5>History</h5>
        <ul className='list-group'>
          {history.map((h, i) => (
            <li key={i} className='list-group-item'>
              {h}
            </li>
          ))}
          <li className='mx-3 p-2'>
            total : {formatTime(totalHours, totalMinutes)}
          </li>
        </ul>
      </div>
      <div className='w-50 p-3'>
        <h3>Total Time: {formatTime(totalHours, totalMinutes)}</h3>

        <div className='mb-2'>
          <input
            type='text'
            className='form-control'
            placeholder='e.g. 2.45'
            value={timeInput}
            onChange={handleInputChange}
          />
          {error && <small className='text-danger'>{error}</small>}
        </div>

        <button
          className='btn btn-success me-2'
          onClick={() => handleOperation(true)}
          disabled={!!error}
        >
          + Add
        </button>
        <button
          className='btn btn-danger'
          onClick={() => handleOperation(false)}
          disabled={!!error}
        >
          – Subtract
        </button>
      </div>
    </div>
  );
};

export default TimeAdder;
