import React, { useState, useEffect } from 'react';
import { ref, push, onValue, set, get, update } from 'firebase/database';
import { database } from '../Firebase';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Modal, Button } from 'react-bootstrap';

export default function ReturnDashboard() {
  const [formData, setFormData] = useState({});
  const [fields, setFields] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [newField, setNewField] = useState({
    label: '',
    name: '',
    type: 'text',
    required: false,
    static: false,
  });

  const getFormattedDate = () => {
    const now = new Date();
    return `${String(now.getDate()).padStart(2, '0')}-${String(
      now.getMonth() + 1
    ).padStart(2, '0')}-${now.getFullYear()}`;
  };

  const getFormattedTimestamp = () => {
    const now = new Date();
    const options = {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
    };
    return now.toLocaleString('en-IN', options).replace(',', '');
  };

  const formattedDate = getFormattedDate();
  const timestamp = getFormattedTimestamp();

  useEffect(() => {
    const templateRef = ref(database, 'fieldTemplates/employee');
    onValue(templateRef, (snapshot) => {
      const data = snapshot.val();
      if (data) setFields(data);
    });
  }, []);

  const handleChange = (e) => {
    setFormData((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const employeeId = formData.employeeId?.trim();
    if (!employeeId) {
      return alert('⚠️ Employee ID is required.');
    }

    const employeeRef = push(ref(database, `employeeReturns/${formattedDate}`));
    await set(employeeRef, {
      ...formData,
      datewithtime: timestamp,
    });

    const itemSets = [];
    Object.keys(formData).forEach((key) => {
      const match = key.match(/^item(\d+)$/i);
      if (match) {
        const index = match[1];
        const name = formData[`item${index}`]?.toLowerCase();
        const size = formData[`size${index}`]?.toLowerCase();
        const quantity = parseInt(formData[`quantity${index}`] || '0', 10);

        if (name && size && quantity > 0) {
          itemSets.push({ name, size, quantity });
        }
      }
    });

    if (itemSets.length === 0) {
      return alert('⚠️ No valid items provided.');
    }

    for (const item of itemSets) {
      const stockRef = ref(database, `stock/${formattedDate}`);
      const snapshot = await get(stockRef);

      let stockUpdated = false;
      if (snapshot.exists()) {
        const data = snapshot.val();
        const matchKey = Object.keys(data).find(
          (key) =>
            data[key].name?.toLowerCase() === item.name &&
            data[key].size?.toLowerCase() === item.size
        );

        if (matchKey) {
          const existing = data[matchKey];
          const existingQty = parseInt(existing.quantity || '0', 10);

          const newQty = existingQty + item.quantity;

          await update(ref(database, `stock/${formattedDate}/${matchKey}`), {
            quantity: String(newQty),
            lastUpdated: timestamp,
          });

          await push(
            ref(database, `stockhistory/${formattedDate}/${employeeId}`),
            {
              ...item,
              change: `+${item.quantity}`,
              quantityBefore: String(existingQty),
              quantityAfter: String(newQty),
              timestamp,
            }
          );

          stockUpdated = true;
        }
      }

      if (!stockUpdated) {
        const newStockRef = push(stockRef);
        await set(newStockRef, {
          name: item.name,
          size: item.size,
          quantity: String(item.quantity),
          datewithtime: timestamp,
        });

        await push(
          ref(database, `stockhistory/${formattedDate}/${employeeId}`),
          {
            ...item,
            change: `+${item.quantity}`,
            quantityBefore: '0',
            quantityAfter: String(item.quantity),
            timestamp,
          }
        );
      }
    }

    alert(
      `✅ Stock increased and employee return recorded for ${formattedDate}`
    );
    setFormData({});
  };

  const handleNewFieldChange = (e) => {
    const { name, value, type, checked } = e.target;
    setNewField((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const addField = () => {
    if (!newField.label || !newField.name) {
      return alert('Label and name are required.');
    }
    const updated = [...fields, newField];
    setFields(updated);
    set(ref(database, 'fieldTemplates/employee'), updated);
    setNewField({
      label: '',
      name: '',
      type: 'text',
      required: false,
      static: false,
    });
  };

  const deleteField = (index) => {
    if (fields[index].static) {
      return alert('❌ Cannot delete static field');
    }
    const updated = [...fields];
    updated.splice(index, 1);
    setFields(updated);
    set(ref(database, 'fieldTemplates/employee'), updated);
  };

  return (
    <div className='container shadow-lg p-4 my-4 bg-white rounded'>
      <h4 className='mb-3 text-center'>Return Employee Stock</h4>
      <h6 className='mb-4 text-center'>{timestamp}</h6>

      <div className='text-end mb-3'>
        <Button variant='secondary' onClick={() => setShowModal(true)}>
          ⚙️ Modify Fields
        </Button>
      </div>

      <form onSubmit={handleSubmit}>
        <div className='row'>
          {fields.map((field, idx) => (
            <div className='col-md-6 pt-3' key={idx}>
              <label className='form-label'>{field.label}</label>
              <input
                type={field.type}
                className='form-control'
                name={field.name}
                value={formData[field.name] || ''}
                onChange={handleChange}
                required={field.required}
                placeholder={`Enter ${field.label}`}
              />
            </div>
          ))}
        </div>
        <div className='text-center mt-4'>
          <button type='submit' className='btn btn-primary px-4'>
            Submit
          </button>
        </div>
      </form>

      <Modal show={showModal} onHide={() => setShowModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Manage Fields</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <h6>Current Fields</h6>
          {fields.map((field, idx) => (
            <div
              key={idx}
              className='d-flex justify-content-between align-items-center mb-2'
            >
              <span>{field.label}</span>
              {!field.static && (
                <Button
                  variant='danger'
                  size='sm'
                  onClick={() => deleteField(idx)}
                >
                  Delete
                </Button>
              )}
            </div>
          ))}
          <hr />
          <h6>Add New Field</h6>
          <input
            type='text'
            className='form-control mb-2'
            name='label'
            placeholder='Label'
            value={newField.label}
            onChange={handleNewFieldChange}
          />
          <input
            type='text'
            className='form-control mb-2'
            name='name'
            placeholder='Name (unique)'
            value={newField.name}
            onChange={handleNewFieldChange}
          />
          <select
            name='type'
            className='form-select mb-2'
            value={newField.type}
            onChange={handleNewFieldChange}
          >
            <option value='text'>Text</option>
            <option value='number'>Number</option>
            <option value='email'>Email</option>
          </select>
          <div className='form-check mb-2'>
            <input
              className='form-check-input'
              type='checkbox'
              name='required'
              checked={newField.required}
              onChange={handleNewFieldChange}
            />
            <label className='form-check-label'>Required</label>
          </div>
          <Button className='w-100' onClick={addField}>
            Add Field
          </Button>
        </Modal.Body>
        <Modal.Footer>
          <Button variant='secondary' onClick={() => setShowModal(false)}>
            Close
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}
